#include <Adafruit_GFX.h>    // 既にインストール済み
#include <Adafruit_ST7735.h> // 新しく「＋」を押したもの

// XIAO ESP32S3のピン配置
#define TFT_RST   2   // D1
#define TFT_DC    3   // D2
#define TFT_CS    4   // D3
#define TFT_SCLK  8   // D8
#define TFT_MOSI 10   // D10

// ライブラリの初期化 (SPIピンを直接指定)
Adafruit_ST7735 tft = Adafruit_ST7735(TFT_CS, TFT_DC, TFT_MOSI, TFT_SCLK, TFT_RST);

void setup() {
  Serial.begin(115200);

  // ST7735液晶の初期化 (黒基板や一般的なモジュールは INITR_BLACKTAB)
  // もし色がおかしい場合は INITR_REDTAB や INITR_GREENTAB に変更してください
  tft.initR(INITR_BLACKTAB);

  // 画面を横向きに設定
  tft.setRotation(1);

  // 画面を黒色でクリア
  tft.fillScreen(ST7735_BLACK);

  // テキストの描画
  tft.setCursor(10, 20);
  tft.setTextColor(ST7735_WHITE);
  tft.setTextSize(2);
  tft.println("XIAO ESP32S3");

  tft.setCursor(10, 50);
  tft.setTextColor(ST7735_GREEN);
  tft.println("ADAFRUIT TEST");

  // 枠線の描画
  tft.drawRect(5, 5, 150, 118, ST7735_BLUE);
}

void loop() {
  // 動作確認用ループ
  tft.setCursor(10, 80);
  tft.setTextColor(ST7735_RED, ST7735_BLACK);
  tft.print("Status: ON ");
  delay(500);

  tft.setCursor(10, 80);
  tft.setTextColor(ST7735_YELLOW, ST7735_BLACK);
  tft.print("Status: ON*");
  delay(500);
}
